import{_ as a,o as r,c as o,ae as e}from"./chunks/framework.BajMXG5H.js";const u=JSON.parse('{"title":"ネイティブmacOS","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/native-macos.md","filePath":"ja/guide/native-macos.md"}'),d={name:"ja/guide/native-macos.md"};function n(s,t,i,l,h,c){return r(),o("div",null,[...t[0]||(t[0]=[e(`<h1 id="ネイティブmacos" tabindex="-1">ネイティブmacOS <a class="header-anchor" href="#ネイティブmacos" aria-label="Permalink to &quot;ネイティブmacOS&quot;">​</a></h1><p>Orchestraは<a href="https://v2.tauri.app/" target="_blank" rel="noreferrer">Tauri</a>で構築されており、最小限のリソース使用量でネイティブなmacOS体験を提供します。</p><h2 id="アーキテクチャ" tabindex="-1">アーキテクチャ <a class="header-anchor" href="#アーキテクチャ" aria-label="Permalink to &quot;アーキテクチャ&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hook (curl) → Rust (axum, port 3008) → Store → Tauri Event → React UI</span></span>
<span class="line"><span>                                              → tmux (Command)</span></span>
<span class="line"><span>                                              → Notification</span></span>
<span class="line"><span>                                              → Sound</span></span></code></pre></div><ul><li><strong>バックエンド</strong>: Rust + axum HTTPサーバー（hook取り込み用）</li><li><strong>フロントエンド</strong>: React + Tailwind CSS</li><li><strong>通信</strong>: Tauriイベント（WebSocket不要）</li></ul><h2 id="リソース使用量" tabindex="-1">リソース使用量 <a class="header-anchor" href="#リソース使用量" aria-label="Permalink to &quot;リソース使用量&quot;">​</a></h2><p>Electronベースの代替手段と異なり、TauriアプリはシステムWebViewを使用するため:</p><ul><li><strong>小さなバイナリサイズ</strong> — 約10MB DMG</li><li><strong>低メモリ使用量</strong> — 通常50MB RAM未満</li><li><strong>高速起動</strong> — ネイティブRustバックエンドが即座に起動</li></ul><h2 id="システム統合" tabindex="-1">システム統合 <a class="header-anchor" href="#システム統合" aria-label="Permalink to &quot;システム統合&quot;">​</a></h2><ul><li><strong>通知</strong> — <code>tauri-plugin-notification</code>でネイティブmacOS通知</li><li><strong>サウンド</strong> — <code>afplay</code>でシステムサウンド（<code>Glass.aiff</code>）を再生</li><li><strong>メニューバー</strong> — アプリ設定を完備した標準macOSメニューバー</li><li><strong>オーバーレイタイトルバー</strong> — クリーンでネイティブなタイトルバーデザイン</li></ul><h2 id="アプリメニュー設定" tabindex="-1">アプリメニュー設定 <a class="header-anchor" href="#アプリメニュー設定" aria-label="Permalink to &quot;アプリメニュー設定&quot;">​</a></h2><p><strong>Orchestra</strong>メニューから以下のトグル設定が利用できます:</p><table tabindex="0"><thead><tr><th>設定</th><th>説明</th><th>デフォルト</th></tr></thead><tbody><tr><td><strong>Desktop Notifications</strong></td><td>システム通知の有効/無効</td><td>On</td></tr><tr><td><strong>Auto-jump to tmux Session</strong></td><td>キュー発火時に自動的にターミナルにフォーカス</td><td>Off</td></tr><tr><td><strong>Show Agent Badges</strong></td><td>セッションカードのAIエージェントバッジの表示/非表示</td><td>On</td></tr><tr><td><strong>Show Cue Lane</strong></td><td>上部のキュー通知バーの表示/非表示</td><td>Off</td></tr></tbody></table><h2 id="ポモドーロタイマー" tabindex="-1">ポモドーロタイマー <a class="header-anchor" href="#ポモドーロタイマー" aria-label="Permalink to &quot;ポモドーロタイマー&quot;">​</a></h2><p>コーディングセッション中の集中力維持をサポートするポモドーロタイマーを内蔵しています。</p><h3 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h3><p>全てのタイマー設定は <strong>Orchestra</strong>メニュー → <strong>Pomodoro Timer</strong> から変更可能:</p><table tabindex="0"><thead><tr><th>設定</th><th>選択肢</th><th>デフォルト</th></tr></thead><tbody><tr><td><strong>Work Duration</strong></td><td>15, 20, 25, 30, 45, 60分</td><td>25分</td></tr><tr><td><strong>Short Break</strong></td><td>3, 5, 10, 15分</td><td>5分</td></tr><tr><td><strong>Long Break</strong></td><td>10, 15, 20, 30分</td><td>15分</td></tr><tr><td><strong>Cycles before Long Break</strong></td><td>2, 3, 4, 5, 6</td><td>4</td></tr><tr><td><strong>Size</strong></td><td>Small, Medium, Large</td><td>Medium</td></tr><tr><td><strong>Show Reset Button</strong></td><td>表示切り替え</td><td>On</td></tr><tr><td><strong>Show Skip Button</strong></td><td>表示切り替え</td><td>On</td></tr></tbody></table><h3 id="サイクル管理" tabindex="-1">サイクル管理 <a class="header-anchor" href="#サイクル管理" aria-label="Permalink to &quot;サイクル管理&quot;">​</a></h3><p><strong>Cycle Status</strong>サブメニューで現在の進捗を確認できます:</p><ul><li><strong>サイクル進捗</strong> — 例: 「Cycle: 2/4」</li><li><strong>現在のフェーズ</strong> — Working、Short Break、Long Break</li><li><strong>Reset All Cycles</strong> — 確認ダイアログ付きでサイクルをリセット</li></ul><h3 id="使い方" tabindex="-1">使い方 <a class="header-anchor" href="#使い方" aria-label="Permalink to &quot;使い方&quot;">​</a></h3><ul><li>タイマーをクリックして開始/一時停止</li><li>Work → Short Break → Work → ... → Long Breakの順に自動で進行</li><li>タイマーをドラッグしてダッシュボード上の好きな位置に移動可能</li><li>休憩開始時に緑色のグローアニメーションが表示</li></ul><h2 id="技術スタック" tabindex="-1">技術スタック <a class="header-anchor" href="#技術スタック" aria-label="Permalink to &quot;技術スタック&quot;">​</a></h2><table tabindex="0"><thead><tr><th>コンポーネント</th><th>技術</th></tr></thead><tbody><tr><td>バックエンド</td><td>Rust + axum</td></tr><tr><td>フロントエンド</td><td>React + Tailwind CSS 4</td></tr><tr><td>デスクトップ</td><td>Tauri v2</td></tr><tr><td>状態管理</td><td><code>Arc&lt;RwLock&lt;Store&gt;&gt;</code></td></tr><tr><td>通知</td><td>tauri-plugin-notification</td></tr></tbody></table>`,25)])])}const p=a(d,[["render",n]]);export{u as __pageData,p as default};
